// Program 12.1: Multiplication table using a for loop
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Table of: ";
    cin >> n;
    for (int i = 1; i <= 10; i++) {
        cout << n << " x " << i << " = " << n * i << endl;
    }
    return 0;
}

// Program 12.2: Sum and average of N numbers
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "How many numbers? ";
    cin >> n;
    double sum = 0;
    for (int i = 1; i <= n; i++) {
        double x;
        cout << "Number " << i << ": ";
        cin >> x;
        sum += x;
    }
    cout << "\nSum = " << sum << endl;
    if (n > 0)
        cout << "Average = " << sum / n << endl;
    return 0;
}

// Program 12.3: Factorial of a number
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter n (0-20): ";
    cin >> n;
    long long fact = 1;
    for (int i = 2; i <= n; i++)
        fact *= i;
    cout << n << "! = " << fact << endl;
    return 0;
}

