// Program 12.4: Sum of digits and reverse of a number (while loop)
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter a positive number: ";
    cin >> n;
    int original = n, sum = 0, rev = 0;
    while (n > 0) {
        int digit = n % 10;     // last digit
        sum += digit;
        rev = rev * 10 + digit;
        n = n / 10;             // remove last digit
    }
    cout << "Sum of digits = " << sum << endl;
    cout << "Reverse       = " << rev << endl;
    if (rev == original)
        cout << original << " is a palindrome." << endl;
    return 0;
}

