// Program 12.9: Guess the number (do-while loop)
#include <iostream>
using namespace std;

int main() {
    const int SECRET = 37;
    int guess, tries = 0;
    do {
        cout << "Guess the number (1-100): ";
        cin >> guess;
        tries++;
        if (guess > SECRET)
            cout << "Too high!" << endl;
        else if (guess < SECRET)
            cout << "Too low!" << endl;
    } while (guess != SECRET);
    cout << "Correct! You took " << tries << " tries." << endl;
    return 0;
}

// Program 12.10: Menu-driven program with do-while and switch
#include <iostream>
using namespace std;

int main() {
    int choice;
    do {
        cout << "\n===== MENU =====\n";
        cout << "1. Square of a number\n";
        cout << "2. Cube of a number\n";
        cout << "3. Exit\n";
        cout << "Your choice: ";
        cin >> choice;

        if (choice == 1 || choice == 2) {
            int n;
            cout << "Enter number: ";
            cin >> n;
            if (choice == 1)
                cout << "Square = " << n * n << endl;
            else
                cout << "Cube = " << n * n * n << endl;
        } else if (choice == 3) {
            cout << "Thank you!" << endl;
        } else {
            cout << "Invalid choice, try again." << endl;
        }
    } while (choice != 3);
    return 0;
}

// Program 12.5: Prime number check (loop with break)
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;
    bool prime = (n >= 2);
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            prime = false;
            break;          // no need to check further
        }
    }
    if (prime)
        cout << n << " is a prime number." << endl;
    else
        cout << n << " is not a prime number." << endl;
    return 0;
}

// Program 12.8: Skip multiples of 3 using continue
#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 15; i++) {
        if (i % 3 == 0)
            continue;       // skip this number
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

// Program 12.6: First N terms of the Fibonacci series
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "How many terms? ";
    cin >> n;
    long long a = 0, b = 1;
    for (int i = 1; i <= n; i++) {
        cout << a << " ";
        long long next = a + b;
        a = b;
        b = next;
    }
    cout << endl;
    return 0;
}

// Program 12.7: Star patterns with nested loops
#include <iostream>
using namespace std;

int main() {
    int rows = 5;

    // Right triangle
    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= i; j++)
            cout << "* ";
        cout << endl;
    }
    cout << endl;

    // Pyramid
    for (int i = 1; i <= rows; i++) {
        for (int s = 1; s <= rows - i; s++)
            cout << " ";
        for (int j = 1; j <= i; j++)
            cout << "* ";
        cout << endl;
    }
    return 0;
}
